/**
 * Cross-language check: the Python capture agent's records (synthetic golden
 * outbox, regenerated by `python -m capture_agent.golden`) satisfy the zod
 * contracts and are accepted by the IngestionGateway. Synthetic frames: not
 * evidence of a real Chert call.
 */
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { CONTRACTS, parseContract, sha256 } from "@/lib/contracts";
import { MemoryBackend } from "@/lib/reference/memory-backend";
import { MemoryBlobStore, createCaptureProject, projectAssetId } from "@/lib/capture";
import { readOutbox, replayOutbox } from "@/lib/capture/outbox-replay";
import { CAPTURE_FIXTURES, expectOk } from "./helpers";

const GOLDEN = resolve(CAPTURE_FIXTURES, "agent-outbox.synthetic");

async function harness(projectId: string) {
  const backend = new MemoryBackend({ now: () => new Date("2026-11-14T20:00:01.000Z") });
  const actor = { userId: "user_agent_replay" };
  expectOk(await createCaptureProject(backend.projects, actor, "Agent replay", projectId));
  return { backend, actor, deps: { assets: backend.assets, ingestion: backend.ingestion, blobs: new MemoryBlobStore(), actor } };
}

describe("capture agent outbox (synthetic golden)", () => {
  const files = readOutbox(GOLDEN);
  const reg = files.registration as { projectId: string; consent: { note: string } };

  it("is labeled synthetic and every record satisfies the zod contracts", async () => {
    expect(reg.consent.note).toMatch(/SYNTHETIC FIXTURE/);
    expect(parseContract(CONTRACTS["source-registration"].schema, files.registration).ok).toBe(true);
    for (const f of files.frames) {
      const parsed = parseContract(CONTRACTS["ingest-envelope"].schema, f.envelope);
      expect(parsed.ok, f.file).toBe(true);
      const env = f.envelope as { projectId: string; frame: { assetId: string; contentHash: string; byteSize: number } };
      // Python's sha256 and asset-id derivation agree with the TypeScript ones.
      expect(env.frame.contentHash).toBe(await sha256(f.bytes));
      expect(env.frame.byteSize).toBe(f.bytes.byteLength);
      expect(env.frame.assetId).toBe(await projectAssetId(env.projectId, "frame", env.frame.contentHash));
    }
    const session = (await import("node:fs")).readFileSync(resolve(GOLDEN, "capture-session.json"), "utf8");
    expect(parseContract(CONTRACTS["capture-session"].schema, JSON.parse(session)).ok).toBe(true);
  });

  it("is accepted by the gateway, including a mid-call dimension change", async () => {
    const h = await harness(reg.projectId);
    const replay = expectOk(await replayOutbox(h.deps, files));
    expect(replay.source.adapter).toBe("chert_facetime");
    const results = replay.entries.map((e) => expectOk(e.result));
    expect(results.map((r) => r.status)).toEqual(["accepted", "accepted", "accepted"]);
    expect(results.at(-1)?.latestSequence).toBe(2);
    const obs = expectOk(await h.backend.ingestion.listObservations(h.actor, reg.projectId, replay.source.id));
    expect(obs.map((o) => [o.frame.width, o.frame.height])).toEqual([
      [64, 48],
      [64, 48],
      [48, 64],
    ]);
  });

  it("replays idempotently and stores late frames as out of order", async () => {
    const h = await harness(reg.projectId);
    const reversed = { ...files, frames: [...files.frames].reverse() };
    const first = expectOk(await replayOutbox(h.deps, reversed));
    expect(first.entries.map((e) => expectOk(e.result).outOfOrder)).toEqual([false, true, true]);
    const again = expectOk(await replayOutbox(h.deps, files));
    expect(again.entries.map((e) => expectOk(e.result).status)).toEqual(["duplicate", "duplicate", "duplicate"]);
  });

  it("rejects a frame whose bytes do not match its envelope", async () => {
    const h = await harness(reg.projectId);
    const swapped = { ...files, frames: [{ ...files.frames[0], bytes: files.frames[1].bytes }] };
    const replay = expectOk(await replayOutbox(h.deps, swapped));
    const result = replay.entries[0].result;
    expect(result.ok ? "ok" : result.error.code).toBe("INVALID_SCHEMA");
  });
});
